CREATE TABLE "consumivel" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "uuid" uuid UNIQUE NOT NULL DEFAULT (gen_random_uuid()),
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  "updated_at" timestamptz,
  "active" boolean NOT NULL DEFAULT true,
  "deleted" boolean NOT NULL DEFAULT false,
  "nome" varchar UNIQUE NOT NULL,
  "preco_kit" numeric(5,2) NOT NULL CHECK (preco_kit > 0),
  "quantidade_kit" int NOT NULL CHECK (quantidade_kit > 0)
);

CREATE TABLE "impressora" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "uuid" uuid UNIQUE NOT NULL DEFAULT (gen_random_uuid()),
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  "updated_at" timestamptz,
  "active" boolean NOT NULL DEFAULT true,
  "deleted" boolean NOT NULL DEFAULT false,
  "nome" varchar UNIQUE NOT NULL,
  "custo_aquisicao" numeric(7,2) NOT NULL CHECK (custo_aquisicao > 0),
  "vida_util_horas" int NOT NULL CHECK (vida_util_horas > 0),
  "potencia_media_ams_w" numeric(6,2) NOT NULL CHECK (potencia_media_ams_w >= 0)
);

CREATE TABLE "impressora_material" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "material_id" int NOT NULL,
  "impressora_id" int NOT NULL,
  "updated_at" timestamptz NOT NULL DEFAULT (now()),
  "potencia_media_w" numeric(6,2) NOT NULL CHECK (potencia_media_w > 0)
);

CREATE TABLE "nivel_desperdicio" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "uuid" uuid UNIQUE NOT NULL DEFAULT (gen_random_uuid()),
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  "updated_at" timestamptz,
  "active" boolean NOT NULL DEFAULT true,
  "deleted" boolean NOT NULL DEFAULT false,
  "nome" varchar UNIQUE NOT NULL,
  "percentual" numeric(4,2) NOT NULL CHECK (percentual > 0)
);

CREATE TABLE "margem_lucro" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "uuid" uuid UNIQUE NOT NULL DEFAULT (gen_random_uuid()),
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  "updated_at" timestamptz,
  "active" boolean NOT NULL DEFAULT true,
  "deleted" boolean NOT NULL DEFAULT false,
  "nome" varchar UNIQUE NOT NULL,
  "percentual" numeric(5,2) NOT NULL CHECK (percentual > 0)
);

CREATE TABLE "energia" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "updated_at" timestamptz NOT NULL DEFAULT (now()),
  "valor_fatura" numeric(5,2) NOT NULL CHECK (valor_fatura > 0),
  "consumo_kwh" int NOT NULL CHECK (consumo_kwh > 0)
);

CREATE TABLE "acabamento" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "updated_at" timestamptz NOT NULL DEFAULT (now()),
  "valor_hora" numeric(5,2) NOT NULL CHECK (valor_hora > 0)
);

CREATE UNIQUE INDEX "uq_material_impressora" ON "impressora_material" ("material_id", "impressora_id");

ALTER TABLE filamento ADD CONSTRAINT ck_filamento_preco_kg CHECK (preco_kg > 0);

ALTER TABLE material DROP COLUMN potencia_media_w;

ALTER TABLE "impressora_material" ADD FOREIGN KEY ("material_id") REFERENCES "material" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "impressora_material" ADD FOREIGN KEY ("impressora_id") REFERENCES "impressora" ("id") DEFERRABLE INITIALLY IMMEDIATE;
